{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Label content for the breadcrumb item.",
      "required": true
    },
    {
      "name": "href",
      "type": "string",
      "description": "URL the breadcrumb links to; omit for non-navigable items."
    },
    {
      "name": "onClick",
      "type": "(e: MouseEvent) => void",
      "description": "Click handler for the breadcrumb item."
    },
    {
      "name": "isCurrent",
      "type": "boolean",
      "description": "Marks this item as the current page, applying aria-current=\"page\". When omitted, the last item is auto-detected if no item is explicitly current; pass false to opt out."
    },
    {
      "name": "startIcon",
      "type": "ReactNode",
      "description": "Icon rendered before the item label.",
      "slotElements": [
        {
          "__element": "Icon",
          "props": {
            "icon": "check",
            "size": "sm"
          }
        }
      ]
    },
    {
      "name": "menu",
      "type": "DropdownMenuOption[] | ReactNode",
      "description": "Menu opened when the item is activated, using the same item API as DropdownMenu/MoreMenu/ContextMenu (a DropdownMenuOption[] array or composed DropdownMenuItem children). Renders a link-styled menu trigger with a chevron and aria-haspopup=\"menu\". Takes precedence over href/onClick."
    },
    {
      "name": "menuSize",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Size passed to the menu items. Defaults from the breadcrumb variant ('supporting' → 'sm', otherwise 'md')."
    },
    {
      "name": "as",
      "type": "LinkComponentType",
      "description": "Custom link component to render instead of <a>. Overrides the provider-level default from LinkProvider. Only applies to non-current items."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
